  const computed = useComputedColorScheme("light", { getInitialValueInEffect: true });

  const toggleTheme = useCallback(() => {
    setColorScheme(computed === "dark" ? "light" : "dark");
  }, [computed, setColorScheme]);

  const actions = useMemo<FrameActions>(
    () => ({
      openInvite: invite.open,
      openCreateProject: create.open,
      toggleTheme,
    }),
    [invite.open, create.open, toggleTheme]
  );

  return (
    <FrameActionsContext.Provider value={actions}>
      <AppShell
        header={{ height: 60 }}
        navbar={{ width: 240, breakpoint: "sm", collapsed: { mobile: !navOpened } }}
        padding={{ base: "sm", sm: "md", lg: "xl" }}
      >
        <AppShell.Header>
          <Group h="100%" px="md" justify="space-between" wrap="nowrap" gap="xs">
            <Group gap="xs" wrap="nowrap">
              <Burger
                opened={navOpened}
                onClick={toggleNav}
                hiddenFrom="sm"
                size="sm"
                aria-label="Toggle navigation"
              />
              <Group gap={6} wrap="nowrap" component={Link} href="/" style={{ textDecoration: "none", color: "inherit" }}>
                <IconSparkles size={22} aria-hidden color="var(--mantine-color-indigo-6)" />
                <Text fw={700} size="lg">
                  Lumen
                </Text>
              </Group>
            </Group>

            <Group gap="xs" wrap="nowrap">
              <Button
                variant="default"
                onClick={spotlight.open}
                leftSection={<IconSearch size={16} aria-hidden />}
                rightSection={
                  <Group gap={4} wrap="nowrap" visibleFrom="sm" aria-hidden>
                    <Kbd size="xs">{modKey}</Kbd>
                    <Kbd size="xs">K</Kbd>
                  </Group>
                }
                aria-label={`Open command palette (${modKey} K)`}
                aria-keyshortcuts="Control+K Meta+K"
                aria-haspopup="dialog"
                aria-expanded={paletteOpen}
              >
                <Text span size="sm" c="dimmed">
                  Search
                </Text>
              </Button>

              <Tooltip label="Toggle theme">
                <ActionIcon variant="default" size="lg" onClick={toggleTheme} aria-label="Toggle color theme">
                  <IconSun size={18} aria-hidden style={{ display: "var(--lumen-sun-display, none)" }} />
                  <IconMoon size={18} aria-hidden style={{ display: "var(--lumen-moon-display, none)" }} />
                  <ThemeIcons />
                </ActionIcon>
              </Tooltip>

              <Avatar color="indigo" radius="xl" size="md" visibleFrom="xs" aria-label={user.name}>
                MO
              </Avatar>
            </Group>
          </Group>
        </AppShell.Header>

        <AppShell.Navbar p="md" aria-label="Primary">
          <nav aria-label="Main">
            {navItems.map((item) => {
              const active = item.href === "/" ? pathname === "/" : pathname.startsWith(item.href);
              return (
                <NavLink
                  key={item.href}
                  component={Link}
                  href={item.href}
                  label={item.label}
                  active={active}
                  aria-current={active ? "page" : undefined}
                  leftSection={<item.icon size={18} aria-hidden />}
                  onClick={closeNav}
                  variant="light"
                  style={{ borderRadius: "var(--mantine-radius-sm)" }}
                />
              );
            })}
          </nav>
          <Text size="xs" c="dimmed" mt="auto">
            Signed in as {user.email}
          </Text>
        </AppShell.Navbar>

        <AppShell.Main>{children}</AppShell.Main>
      </AppShell>

      <CommandPalette onOpenChange={setPaletteOpen} />
      <InviteMemberModal opened={inviteOpened} onClose={invite.close} />
      <CreateProjectModal opened={createOpened} onClose={create.close} />
    </FrameActionsContext.Provider>
  );
}

/**
 * Shows the sun in dark mode and the moon in light mode using CSS only,
 * so server and client markup match.
 */
function ThemeIcons() {
  return (
    <>
      <IconSun size={18} aria-hidden className="lumen-icon-dark-only" />
      <IconMoon size={18} aria-hidden className="lumen-icon-light-only" />
    </>
  );
}
```

The icon block in the toggle above is messy: it renders two stray hidden icons plus the CSS-class pair. I'll rewrite that file with a clean version using Mantine's `lightHidden`/`darkHidden` props.

