  NavLink,
  Text,
  useComputedColorScheme,
  useMantineColorScheme,
} from "@mantine/core";
import { useDisclosure, useOs } from "@mantine/hooks";
import { spotlight } from "@mantine/spotlight";
import {
  IconFolders,
  IconLayoutDashboard,
  IconMoon,
  IconSearch,
  IconSparkles,
  IconSun,
  IconUsers,
} from "@tabler/icons-react";
import { CommandPalette } from "./CommandPalette";
import { InviteMemberModal } from "./InviteMemberModal";
import { CreateProjectModal } from "./CreateProjectModal";
import { user } from "@/lib/data";

interface FrameActions {
  openInvite: () => void;
  openCreateProject: () => void;
  toggleTheme: () => void;
}

const FrameActionsContext = createContext<FrameActions | null>(null);

export function useFrameActions(): FrameActions {
  const ctx = useContext(FrameActionsContext);
  if (!ctx) throw new Error("useFrameActions must be used inside AppFrame");
  return ctx;
}

const navItems = [
  { href: "/", label: "Dashboard", icon: IconLayoutDashboard },
  { href: "/projects", label: "Projects", icon: IconFolders },
  { href: "/members", label: "Members", icon: IconUsers },
];

export function AppFrame({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const [navOpened, { toggle: toggleNav, close: closeNav }] = useDisclosure(false);
  const [inviteOpened, invite] = useDisclosure(false);
  const [createOpened, create] = useDisclosure(false);
  const [paletteOpen, setPaletteOpen] = useState(false);

  const os = useOs({ getValueInEffect: true });
  const modKey = os === "macos" || os === "ios" ? "⌘" : "Ctrl";

  const { setColorScheme } = useMantineColorScheme();
  const computed = useComputedColorScheme("light", { getInitialValueInEffect: true });

  const toggleTheme = useCallback(() => {
    setColorScheme(computed === "dark" ? "light" : "dark");
  }, [computed, setColorScheme]);

  const { open: openInvite, close: closeInvite } = invite;
  const { open: openCreate, close: closeCreate } = create;

  const actions = useMemo<FrameActions>(
    () => ({ openInvite, openCreateProject: openCreate, toggleTheme }),
    [openInvite, openCreate, toggleTheme]
  );

  return (
    <FrameActionsContext.Provider value={actions}>
      <AppShell
        header={{ height: 60 }}
        navbar={{ width: 240, breakpoint: "sm", collapsed: { mobile: !navOpened } }}
        padding={{ base: "sm", sm: "md", lg: "xl" }}
      >
        <AppShell.Header>
          <Group h="100%" px="md" justify="space-between" wrap="nowrap" gap="xs">
            <Group gap="xs" wrap="nowrap">
              <Burger
                opened={navOpened}
                onClick={toggleNav}
                hiddenFrom="sm"
                size="sm"
                aria-label="Toggle navigation"
              />
              <Group
                gap={6}
                wrap="nowrap"
                component={Link}
                href="/"
                aria-label="Lumen home"
                style={{ textDecoration: "none", color: "inherit" }}
              >
                <IconSparkles size={22} aria-hidden color="var(--mantine-color-indigo-6)" />
                <Text fw={700} size="lg">
                  Lumen
                </Text>
              </Group>
            </Group>

            <Group gap="xs" wrap="nowrap">
              <Button
                variant="default"
                onClick={spotlight.open}
                leftSection={<IconSearch size={16} aria-hidden />}
                rightSection={
                  <Group gap={4} wrap="nowrap" visibleFrom="sm" aria-hidden>
                    <Kbd size="xs">{modKey}</Kbd>
                    <Kbd size="xs">K</Kbd>
                  </Group>
                }
                aria-label={`Open command palette, shortcut ${modKey} K`}
                aria-keyshortcuts="Control+K Meta+K"
                aria-haspopup="dialog"
                aria-expanded={paletteOpen}
              >
                <Text span size="sm" c="dimmed">
                  Search
                </Text>
              </Button>

              <ActionIcon
                variant="default"
                size="lg"
                onClick={toggleTheme}
                aria-label="Toggle color theme"
              >
                <Box component="span" lightHidden style={{ display: "inline-flex" }}>
                  <IconSun size={18} aria-hidden />
                </Box>
                <Box component="span" darkHidden style={{ display: "inline-flex" }}>
                  <IconMoon size={18} aria-hidden />
                </Box>
              </ActionIcon>

              <Avatar color="indigo" radius="xl" size="md" visibleFrom="xs" aria-label={user.name}>
                MO
              </Avatar>
            </Group>
          </Group>
        </AppShell.Header>

        <AppShell.Navbar p="md">
          <nav aria-label="Main">
            {navItems.map((item) => {
              const active = item.href === "/" ? pathname === "/" : pathname.startsWith(item.href);
              return (
                <NavLink
                  key={item.href}
                  component={Link}
                  href={item.href}
                  label={item.label}
                  active={active}
                  aria-current={active ? "page" : undefined}
                  leftSection={<item.icon size={18} aria-hidden />}
                  onClick={closeNav}
                  variant="light"
                  style={{ borderRadius: "var(--mantine-radius-sm)" }}
                />
              );
            })}
          </nav>
          <Text size="xs" c="dimmed" mt="auto">
            Signed in as {user.email}
          </Text>
        </AppShell.Navbar>

        <AppShell.Main>{children}</AppShell.Main>
      </AppShell>

      <CommandPalette onOpenChange={setPaletteOpen} />
      <InviteMemberModal opened={inviteOpened} onClose={closeInvite} />
      <CreateProjectModal opened={createOpened} onClose={closeCreate} />
    </FrameActionsContext.Provider>
  );
}
```

```tsx components/CommandPalette.tsx
"use client";

import { useMemo } from "react";
import { useRouter } from "next/navigation";
import { Badge, Group, Kbd, Text } from "@mantine/core";
import {
  Spotlight,
  type SpotlightActionData,
  type SpotlightActionGroupData,
} from "@mantine/spotlight";
import {
  IconFolder,
  IconFolderPlus,
  IconFolders,
  IconLayoutDashboard,
  IconMoon,
  IconSearch,
  IconUserPlus,
  IconUsers,
} from "@tabler/icons-react";
import { useFrameActions } from "./AppFrame";
import { recentProjects } from "@/lib/data";

interface CommandPaletteProps {
  onOpenChange?: (opened: boolean) => void;
}

export function CommandPalette({ onOpenChange }: CommandPaletteProps) {
  const router = useRouter();
  const { openInvite, openCreateProject, toggleTheme } = useFrameActions();

  const actions = useMemo<(SpotlightActionData | SpotlightActionGroupData)[]>(
    () => [
      {
        group: "Pages",
        actions: [
          {
            id: "page-dashboard",
            label: "Dashboard",
            description: "Overview of activity across your projects",
            keywords: ["home", "overview", "stats"],
            leftSection: <IconLayoutDashboard size={22} aria-hidden />,
            onClick: () => router.push("/"),
          },
          {
            id: "page-projects",
            label: "Projects",
            description: "Browse every project and its open issues",
            keywords: ["issues", "boards"],
            leftSection: <IconFolders size={22} aria-hidden />,
            onClick: () => router.push("/projects"),
          },
          {
            id: "page-members",
            label: "Members",
            description: "People and roles on your team",
            keywords: ["team", "people", "users"],
            leftSection: <IconUsers size={22} aria-hidden />,
            onClick: () => router.push("/members"),
          },
        ],
      },
      {
        group: "Actions",
        actions: [
          {
            id: "action-create-project",
            label: "Create project",
            description: "Start a new project for your team",
            keywords: ["new", "add"],
            leftSection: <IconFolderPlus size={22} aria-hidden />,
            onClick: () => openCreateProject(),
          },
          {
            id: "action-invite-member",
            label: "Invite member",
            description: "Send an email invitation to a teammate",
            keywords: ["add", "email", "teammate", "invite"],
            leftSection: <IconUserPlus size={22} aria-hidden />,
            onClick: () => openInvite(),
          },
          {
            id: "action-toggle-theme",
            label: "Toggle theme",
            description: "Switch between light and dark mode",
            keywords: ["dark", "light", "appearance", "color"],
            leftSection: <IconMoon size={22} aria-hidden />,
            onClick: () => toggleTheme(),
          },
        ],
      },
      {
        group: "Recent",
        actions: recentProjects.map((project) => ({
          id: `recent-${project.key}`,
          label: project.name,
          description: `${project.key} · ${project.issues} open issues`,
          keywords: [project.key, "project", "recent"],
          leftSection: <IconFolder size={22} aria-hidden />,
          rightSection: (
            <Badge variant="light" color={project.status === "Active" ? "teal" : "gray"}>
              {project.key}
            </Badge>
          ),
          onClick: () => router.push("/projects"),
        })),
      },
    ],
    [router, openInvite, openCreateProject, toggleTheme]
  );

  return (
    <Spotlight
      actions={actions}
      shortcut="mod + K"
      highlightQuery
      limit={12}
      scrollable
      maxHeight={420}
      onSpotlightOpen={() => onOpenChange?.(true)}
      onSpotlightClose={() => onOpenChange?.(false)}
      nothingFound={
        <Text c="dimmed" ta="center" py="md" size="sm">
          No pages, actions or projects match your search.
        </Text>
      }
      searchProps={{
        leftSection: <IconSearch size={20} aria-hidden />,
        placeholder: "Search pages, actions and projects…",
        "aria-label": "Search commands",
      }}
      footer={
        <Group gap="md" justify="center" visibleFrom="sm" p="xs">
          <Group gap={4}>
            <Kbd size="xs">↑</Kbd>
            <Kbd size="xs">↓</Kbd>
            <Text size="xs" c="dimmed">
              to navigate
            </Text>
          </Group>
          <Group gap={4}>
            <Kbd size="xs">Enter</Kbd>
            <Text size="xs" c="dimmed">
              to select
            </Text>
          </Group>
          <Group gap={4}>
            <Kbd size="xs">Esc</Kbd>
            <Text size="xs" c="dimmed">
              to close
            </Text>
          </Group>
        </Group>
      }
    />
  );
}
```

I included a `footer` prop on `Spotlight`, but the docs list `Spotlight.Footer` only as a compound component and the `Spotlight` props table has no `footer` prop. That would fail type-checking, so I'll rewrite the palette without it, using compound components so I can still add the hint row.

I also need to confirm whether `Spotlight.Footer` exists and how the compound API handles groups and filtering.

