function initials(name: string): string {
  return name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("");
}

export function MembersScreen() {
  return (
    <Stack gap="lg">
      <div>
        <Title order={1} size="h2">
          Members
